            weights[k][:] = original[k]

def project_out(layer, u, parts=('self_attn.o_proj.weight','mlp.down_proj.weight')):
    u = u.astype(np.float32)
    for p in parts:
        W = weights[f'model.layers.{layer}.{p}']
        W -= np.outer(u, u @ W)

